// Central technology registry (Identity & Polish nav pass): single source
// of truth mapping a slug to { name, url, icon } for every technology
// reference site-wide (Projects' technologies field, the Hub's Tech Stack
// section, Workbench). Consumers never hardcode a name, link, or icon a
// second time — see TechBadge.astro's Technology Badge pattern.
//
// Icon sourcing (flagged): monochrome path data vendored from
// simple-icons (MIT-licensed), fetched once from its
// GitHub repo and stored here as plain path strings rather than added as
// an npm dependency — consistent with this project's self-hosted-
// everything posture (self-hosted fonts, no CDN). A real npm
// dependency was also a worse practical fit: several needed marks
// (VTK, Ninja) aren't in simple-icons at all, so a mixed
// "some vendored, some from a package" pipeline would have bought
// nothing but a second sourcing path to maintain.
//
// Rendered with `fill="currentColor"` by the consuming component, never
// baked into the path data itself, so accent theming applies
// automatically. A registry entry with no `icon` renders name-only —
// still linked, still styled — rather than inventing a mark for a
// technology with no clean official monochrome logo available (Ninja,
// flagged below).
//
// One entry (`vtk`) departs from the simple-icons sourcing path: its
// mark was user-supplied (not present in simple-icons), normalized here
// to the same { viewBox, path } shape as every other entry — coordinates
// left in their native canvas rather than hand-rescaled to "0 0 24 24"
// (risk of arithmetic error outweighs a cosmetic viewBox match; the
// TechIcon type already carries viewBox per-entry for exactly this
// case), and its `style="fill:#…"` stripped so it renders via
// currentColor like every other badge. Flagged for license clarity:
// this path data is not MIT-licensed simple-icons content — it's
// Kitware's VTK wordmark, used here in the ordinary "this is a
// technology I use" sense any project reasonably applies to a logo it
// references, not redistributed as a standalone asset.

export interface TechIcon {
  viewBox: string;
  path: string;
  // Most vendored marks rely on the SVG default (nonzero) and omit this.
  // Set to 'evenodd' when the source mark needs it to render its cutouts
  // correctly (e.g. zed, vscode below) — TechBadge passes it through as
  // the <path>'s fill-rule attribute.
  fillRule?: 'evenodd';
}

export interface Technology {
  name: string;
  url: string;
  icon?: TechIcon;
}

