/**
 * Resolves a free-text technology reference (as authored in existing
 * frontmatter, e.g. "TypeScript", "Node.js") to its registry slug, so
 * content doesn't need to be rewritten to slug form for TechChips to
 * pick it up. Tries an exact slug match first, then a case-insensitive
 * match against each entry's display name. Returns undefined for
 * anything unregistered — the caller's fallback path (a plain,
 * non-interactive chip) handles that case.
 */
export function findTechnologySlug(value: string): string | undefined {
  const normalized = value.trim().toLowerCase();
  if (technologies[normalized]) return normalized;
  const entry = Object.entries(technologies).find(
    ([, tech]) => tech.name.toLowerCase() === normalized,
  );
  return entry?.[0];
}
